window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[282]={"id":"282","numero":282,"titre":"Maladies inflammatoires chroniques de l'intestin (MICI)","objectifs":[{"id":"282-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<div class=\"notion-course\"><p><span>Les</span> <strong><span><span class=\"nc-pink nc-bold\">MICI</span></span></strong> sont des maladies qui résultent de l'<span>inflammation chronique</span>, intermittente ou <span class=\"nc-yellow_bg\">continue</span>, d'une partie du <span>tube digestif</span>. Elles regroupent trois entités :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-pink_bg\">Maladie de Crohn</span></span></strong></td><td>Atteinte possible de <strong>tout le tube digestif</strong> (de la bouche à l'<span class=\"nc-red_bg\">anus</span>) ; <span class=\"nc-red_bg\">inflammation </span><span><span class=\"nc-red_bg\">transmurale</span></span> et <strong>discontinue</strong> (<span class=\"nc-green_bg\">intervalles de muqueuse saine</span>)</td></tr>\n          <tr><td><strong><span><span class=\"nc-pink nc-bold\">Rectocolite hémorragique</span> (<span class=\"nc-pink nc-bold\">RCH</span>)</span></strong></td><td><span class=\"nc-red nc-bold\">Atteinte</span> limitée au <strong>rectum et au <span class=\"nc-red_bg\">côlon</span></strong> ; <span class=\"nc-green_bg\">inflammation </span><span><span class=\"nc-green_bg\">superficielle</span></span> et <strong><span class=\"nc-red nc-bold\">continue</span></strong>, à extension rétrograde, <span class=\"nc-red nc-bold\">sans intervalle sain</span></td></tr>\n          <tr><td><strong><span><span class=\"nc-red nc-bold\">Colite inclassée</span></span></strong></td><td>Quand la distinction Crohn / <span>RCH</span> n'est pas possible (<span>5-10 %</span> des cas)</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span>évolution</span> se fait le plus souvent par <span><span class=\"nc-red_bg\">poussées</span></span><span class=\"nc-red_bg\"> de quelques semaines</span>, entrecoupées de <span class=\"nc-green_bg\">périodes de </span><span><span class=\"nc-green_bg\">rémission</span></span>.</p>\n      <div class=\"obj-callout warning\">\n        <strong>À retenir.</strong> La distinction <span class=\"nc-pink nc-bold\">Crohn</span> / <span><span class=\"nc-pink nc-bold\">RCH</span></span> devient importante si une <span>chirurgie d'exérèse</span> est envisagée. <span class=\"nc-red_bg\">Dans</span> <span>5-10 %</span> des cas elle reste impossible : c'est la <span><span class=\"nc-red nc-bold\">colite inclassée</span></span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span>Syndrome de l</span>’intestin irritable (SII)</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"282-2","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales lésions macroscopiques et microscopiques de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span><span class=\"nc-blue nc-bold\">biopsies</span></span> sont réalisées lors de l'<span><span class=\"nc-blue_bg\">endoscopie</span></span> en <strong><span class=\"nc-blue nc-bold\">zone lésée</span> ET en <span class=\"nc-blue nc-bold\">zones macroscopiquement saines</span></strong> (<span class=\"nc-red nc-bold\">atteinte discontinue</span> dans <span class=\"nc-pink nc-bold\">Crohn</span>, <span class=\"nc-green nc-bold\">continue</span> dans la <span><span class=\"nc-pink nc-bold\">RCH</span></span>). Lésions communes : <span><span class=\"nc-purple nc-bold\">ulcérations</span></span>, <span><span class=\"nc-purple nc-bold\">raréfaction des glandes</span></span>, <span>infiltrat lymphoplasmocytaire</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th></th><th><span><span class=\"nc-pink_bg\">Maladie de Crohn</span></span></th><th><span><span class=\"nc-pink nc-bold\">Rectocolite </span><span><span class=\"nc-pink nc-bold\">hémorragique</span></span></span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Lésions macroscopiques</strong></td>\n            <td>\n              <strong>Topographie :</strong> tout le tube digestif, <span class=\"nc-red nc-bold\">atteinte </span><strong><span class=\"nc-red nc-bold\">discontinue</span></strong><br>\n              <strong><span class=\"nc-red_bg\">Anus</span> :</strong> lésions anopérinéales (≈ <span>50 %</span>)<br>\n              <strong>Rectum :</strong> atteint <span class=\"nc-red_bg\">dans</span> seulement <span>25 %</span><br>\n              <strong>Iléon :</strong> <span class=\"nc-blue_bg\">ulcérations</span> iléales (≈ <span>60 %</span>)<br>\n              <strong><span class=\"nc-red_bg\">Sténoses</span> / fistules :</strong> <span class=\"nc-red_bg\">fréquentes</span> (<span class=\"nc-red_bg\">inflammation </span><span><span class=\"nc-red_bg\">transmurale</span></span>)\n            </td>\n            <td><span class=\"nc-pink nc-bold\">RCH</span> typique : <span class=\"nc-red nc-bold\">atteinte</span> muqueuse continue à partir du rectum, limitée au <span class=\"nc-red_bg\">côlon</span> ; des exceptions existent, notamment sous traitement ou en pédiatrie. Fistules et lésions anopérinéales complexes orientent vers <span class=\"nc-pink nc-bold\">Crohn</span>. Toute <span class=\"nc-orange nc-bold\">sténose</span> colique doit être explorée, notamment pour exclure un cancer.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Inflammation</span> &amp; <span class=\"nc-red_bg\">ulcérations</span> (histo)</strong></td>\n            <td>\n              <span class=\"nc-red_bg\">Inflammation </span><span><span class=\"nc-red_bg\">transmurale</span></span> (toutes <span>les</span> couches)<br>\n              <span class=\"nc-red_bg\">Ulcérations</span> <strong><span class=\"nc-red nc-bold\">fissuraires</span></strong><br>\n              <span><span class=\"nc-blue_bg\">Micro-abcès cryptiques</span></span> : <strong>moins nombreux</strong>\n            </td>\n            <td>\n              <span class=\"nc-green_bg\">Inflammation </span><span><span class=\"nc-green_bg\">superficielle</span></span> (muqueuse + sous-muqueuse superficielle)<br>\n              <span class=\"nc-red_bg\">Ulcérations</span> <strong>non <span class=\"nc-red nc-bold\">fissuraires</span></strong><br>\n              <span><span class=\"nc-blue_bg\">Micro-abcès cryptiques</span></span> : <strong><span class=\"nc-blue_bg\">très nombreux</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glandes &amp; infiltrat</strong></td>\n            <td>\n              <span class=\"nc-blue_bg\">Distorsions glandulaires</span> ; <span class=\"nc-green_bg\">mucosécrétion peu altérée</span><br>\n              Infiltrat plasmocytaire du chorion, voire transmural, sous forme de <strong><span><span class=\"nc-red nc-bold\">nodules lymphoïdes</span></span></strong><br>\n              <strong><span><span class=\"nc-yellow_bg\">Granulomes épithélioïdes et gigantocellulaires</span></span></strong><span class=\"nc-yellow_bg\"> sans </span><span><span class=\"nc-yellow_bg\">nécrose</span></span><span class=\"nc-yellow_bg\"> caséeuse</span> : très évocateurs mais présents dans <span>30 %</span> des cas seulement\n            </td>\n            <td>\n              <span class=\"nc-blue_bg\">Bifurcations et distorsions glandulaires</span> ; <span class=\"nc-red_bg\">mucosécrétion </span><strong><span class=\"nc-red_bg\">très altérée</span></strong><br>\n              <span class=\"nc-yellow_bg\">Infiltrat surtout lymphoplasmocytaire du chorion</span> ; <span><span class=\"nc-yellow_bg\">plasmocytose basale</span></span><br>\n              <span>Jamais de granulome épithélioïde</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">\n        <strong>Discriminant clé.</strong> <span>Les</span> <span>granulomes épithélioïdes sans nécrose caséeuse</span> orientent vers la <span><span class=\"nc-pink_bg\">maladie de Crohn</span></span> ; leur absence et la présence d'une <span class=\"nc-orange_bg\">inflammation</span> strictement superficielle <span class=\"nc-green nc-bold\">continue</span> orientent vers la <span><span class=\"nc-pink nc-bold\">RCH</span></span>.\n      </div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les tableaux opposent les présentations typiques. Une <span class=\"nc-pink nc-bold\">RCH</span> traitée peut avoir une distribution moins <span class=\"nc-red nc-bold\">continue</span> ; une iléite de reflux peut accompagner une pancolite. Une sténose colique est possible et doit faire rechercher une dysplasie/cancer. Ces exceptions ne transforment pas toute lésion en <span class=\"nc-pink_bg\">maladie de Crohn</span>.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"282-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principes physiopathologiques de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<div class=\"notion-course\"><p>La cause des <span>MICI</span> n'est <strong>pas identifiée</strong> et la <span>physiopathologie</span> reste mal connue. La réaction <span><span class=\"nc-purple nc-bold\">inflammatoire</span></span> qui induit <span>les</span> lésions intestinales et extra-intestinales fait intervenir des <span>facteurs <span class=\"nc-red nc-bold\">génétiques</span></span>, des <span><span class=\"nc-red nc-bold\">facteurs environnementaux</span></span>, le <span>microbiote fécal (<span class=\"nc-red nc-bold\">dysbiose</span>)</span> et des <span><span class=\"nc-yellow_bg\">anomalies</span> de la réponse immunitaire</span>.</p>\n      <p>L'<span class=\"nc-orange_bg\">inflammation</span> chronique peut entraîner une <span>fibrose intestinale</span> évoluant vers une <strong>sténose</strong> (surtout <span class=\"nc-red nc-bold\">au niveau du grêle dans la </span><span><span class=\"nc-red nc-bold\">maladie de Crohn</span></span>) et augmente le <span class=\"nc-red_bg\">risque de</span> <span><span class=\"nc-red nc-bold\">cancer colorectal</span></span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Facteur</th><th><span><span class=\"nc-pink_bg\">Maladie de Crohn</span></span></th><th><span><span class=\"nc-pink nc-bold\">Rectocolite </span><span><span class=\"nc-pink nc-bold\">hémorragique</span></span></span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Génétique</span></strong></td><td><span class=\"nc-pink nc-bold\">Mutation </span><span><span class=\"nc-pink nc-bold\">CARD15-NOD2</span></span> (aucune utilité diagnostique)</td><td>Facteurs <span class=\"nc-red nc-bold\">génétiques</span> sans marqueur spécifique</td></tr>\n          <tr><td><strong><span>Tabac</span></strong></td><td><span class=\"nc-red_bg\">Effet </span><span><span class=\"nc-red_bg\">aggravant</span></span> (<span>30-50 %</span> de fumeurs) → l'<strong>arrêt du <span>tabac</span> est une priorité</strong></td><td>Effet <strong>protecteur</strong> (<span>&lt; 10 %</span> de fumeurs)</td></tr>\n          <tr><td><strong>Appendicectomie</strong></td><td>ATCD = <strong><span>facteur de risque</span></strong></td><td>ATCD ± facteur <strong>protecteur</strong></td></tr>\n          <tr><td><strong><span>Sérologie</span></strong></td><td><span>ASCA</span> souvent <span class=\"nc-green nc-bold\">positifs</span> (<span class=\"nc-blue nc-bold\">pANCA</span> <span class=\"nc-red nc-bold\">négatifs</span>)</td><td><span><span class=\"nc-blue nc-bold\">pANCA</span></span> souvent <span class=\"nc-green nc-bold\">positifs</span> (ASCA <span class=\"nc-red nc-bold\">négatifs</span>)</td></tr>\n          <tr><td><strong><span>Épidémiologie</span></strong></td><td><span>Prévalence</span> ≈ <span>1/1000</span> ; <span>incidence</span> <span>5-10/100 000/an</span> ; pic <span><span class=\"nc-blue nc-bold\">20-30 ans</span></span></td><td><span>Prévalence</span> ≈ <span>1/1000</span> ; <span>incidence</span> <span>5-10/100 000/an</span> ; <span class=\"nc-pink_bg\">adulte jeune</span> + 2<sup>e</sup> pic à <span><span class=\"nc-blue nc-bold\">60 ans</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><span>Terrain</span> commun : sujets <strong>jeunes</strong>, sex-ratio ≈ <span>1H/1F</span>, <span class=\"nc-brown_bg\">gradient </span><strong><span class=\"nc-brown_bg\">Nord-Sud</span></strong> (incidences <span>les</span> plus élevées en Amérique du Nord et en <span class=\"nc-red nc-bold\">Europe septentrionale</span>).</p>\n      <div class=\"obj-callout warning\">\n        <strong>Piège classique.</strong> La <span class=\"nc-pink nc-bold\">mutation </span><span><span class=\"nc-pink nc-bold\">CARD15-NOD2</span></span> n'a <strong>aucune utilité diagnostique</strong> : ne jamais la proposer comme examen pour poser le diagnostic de <span class=\"nc-pink nc-bold\">Crohn</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — Spondylarthrite <span>inflammatoire</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>L’association épidémiologique du tabac avec la RCH n’est pas une recommandation de fumer. Le sevrage reste recommandé pour la santé globale ; ni ASCA ni pANCA ne remplacent le faisceau diagnostique.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"282-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","contenu":"<div class=\"notion-course\"><p>Trois manifestations digestives chroniques sont <span>les</span> plus fréquentes et doivent faire évoquer une <span>MICI</span>, surtout chez un <strong>sujet jeune</strong> : <span><span class=\"nc-blue_bg\">diarrhée chronique</span></span> (sécrétoire ou exsudative), <span><span class=\"nc-blue_bg\">douleurs abdominales chroniques</span></span> et <span><span class=\"nc-red nc-bold\">amaigrissement</span> / altération de l'état général</span>. Les <strong><span class=\"nc-orange nc-bold\">symptômes</span> <span class=\"nc-orange nc-bold\">nocturnes</span> qui réveillent le patient</strong> sont un argument fort en faveur d'une cause organique.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Tableau révélateur</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red_bg\">Atteinte rectale</span> / colique (surtout <span>RCH</span>)</strong></td>\n            <td><span class=\"nc-blue_bg\">Épreintes</span> : douleurs coliques et contractions expulsives précédant l’exonération. Ténesme : tension douloureuse anorectale persistante avec besoin insatisfait.</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte anopérinéale (Crohn)</strong></td>\n            <td>Présente chez ≈ <span>30 %</span> des Crohn (absente <span class=\"nc-red_bg\">dans</span> la <span><span class=\"nc-pink nc-bold\">RCH</span></span>) : <span>fistules</span>, <span>fissures</span> (parfois indolores, latérales), <span class=\"nc-blue_bg\">ulcérations</span>, <span class=\"nc-orange_bg\">sténose anale</span>, <span class=\"nc-orange_bg\">marisques</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Manifestations extra-digestives</span> inflammatoires</strong></td>\n            <td>\n              <strong>Ophtalmo :</strong> <span><span class=\"nc-red_bg\">uvéite</span></span>, <span class=\"nc-red_bg\">épisclérite</span>, <span class=\"nc-red_bg\">sclérite</span><br>\n              <strong>Cutanéo-muqueux :</strong> <span><span class=\"nc-blue_bg\">aphtes buccaux</span></span>, <span><span class=\"nc-red_bg\">érythème noueux</span></span>, <span><span class=\"nc-red_bg\">pyoderma gangrenosum</span></span><br>\n              <strong>Articulaire :</strong> <span><span class=\"nc-blue_bg\">arthrites</span></span>, <span class=\"nc-blue_bg\">douleurs articulaires</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Comorbidités</span> associées</strong></td>\n            <td>\n              Maladies associées mais <strong><span class=\"nc-green_bg\">dissociées de l'activité de la </span><span><span class=\"nc-green_bg\">MICI</span></span></strong> :<br>\n              <strong><span><span class=\"nc-orange_bg\">Cholangite sclérosante primitive</span></span> :</strong> <span class=\"nc-red nc-bold\">plus fréquente dans la</span> <span><span class=\"nc-pink nc-bold\">RCH</span></span>, <span>augmente le <span class=\"nc-red_bg\">risque de</span> CCR</span><br>\n              <strong><span><span class=\"nc-orange_bg\">Spondylarthrite ankylosante</span></span> :</strong> sacro-iliite radiologique (<span>10-20 %</span>, asymptomatique, évolue parallèlement à l'<span class=\"nc-red nc-bold\">atteinte</span> digestive) ; forme axiale complète (<span>&lt; 5 %</span>, évolue indépendamment de l'<span class=\"nc-red nc-bold\">atteinte</span> digestive)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Modes de révélation particuliers</strong></td>\n            <td><span class=\"nc-pink nc-bold\">Crohn</span> peut <span class=\"nc-orange nc-bold\">débuter</span> comme une <span><span class=\"nc-orange nc-bold\">gastro-entérite</span></span> <span class=\"nc-red_bg\">dans</span> <span>10 %</span> des cas ; parfois révélé par une complication ; <span>masse</span> de la FID possible (<span><span class=\"nc-red nc-bold\">abcès</span></span> ou atteinte iléocæcale)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout danger\">\n        <strong>Piège annale.</strong> <span>Les</span> <span><span class=\"nc-blue_bg\">ulcérations</span> génitales</span> ne font PAS partie des <span>manifestations extra-digestives</span> des <span><span class=\"nc-pink nc-bold\">MICI</span></span> (réponse comptée fausse en annale). Penser à la <span class=\"nc-pink nc-bold\">maladie de </span><span><span class=\"nc-pink nc-bold\">Behçet</span></span> devant des <span class=\"nc-blue_bg\">ulcérations</span> génitales.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 285 — <span><span class=\"nc-blue_bg\">Diarrhée</span></span><span class=\"nc-blue_bg\"> chronique</span> · 284 — <span><span class=\"nc-red nc-bold\">Syndrome de</span> l</span>’intestin irritable (SII) · 251 — <span><span class=\"nc-red nc-bold\">Amaigrissement</span></span> · 197 — Spondylarthrite <span>inflammatoire</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":7},{"id":"282-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires permettant de poser le diagnostic d’une MICI et les arguments du diagnostic : endocopie, histologie, imagerie (IRM)","contenu":"<div class=\"notion-course\"><p>Le diagnostic repose sur un <strong>faisceau d'arguments</strong> biologiques, endoscopiques, histologiques et radiologiques — aucun examen n'est isolément spécifique.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Examen</th><th>Apport / arguments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <strong><span><span class=\"nc-blue_bg\">Syndrome inflammatoire</span></span> :</strong> <span><span class=\"nc-brown_bg\">CRP</span></span> ↑, hyperleucocytose à PNN, thrombocytose<br>\n              <strong><span class=\"nc-orange_bg\">Anémie</span> :</strong> <span class=\"nc-brown_bg\">ferriprive</span>, <span><span class=\"nc-brown_bg\">inflammatoire</span></span>, ± carence <span>B12</span> (iléite/résection iléale) ou <span>folates</span> (<span class=\"nc-red nc-bold\">grêle proximal</span>)<br>\n              <strong><span><span class=\"nc-brown_bg\">Albuminémie</span></span> :</strong> <span class=\"nc-orange_bg\">hypoalbuminémie</span> (entéropathie exsudative, <span class=\"nc-orange_bg\">dénutrition</span>)\n            </td>\n          </tr>\n          <tr><td colspan=\"5\">Une calprotectine basse réduit la probabilité d’une MICI active, surtout colique, mais n’exclut pas toutes les atteintes, notamment certaines formes isolées du grêle. Elle s’interprète avec clinique, biologie et explorations.</td></tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Endoscopie</span></span></strong></td>\n            <td>\n              <strong><span><span class=\"nc-blue_bg\">FOGD</span></span> + <span class=\"nc-blue_bg\">iléo-</span><span><span class=\"nc-blue_bg\">coloscopie</span></span></strong> avec <span><span class=\"nc-blue nc-bold\">biopsies</span> en <span class=\"nc-blue nc-bold\">zone lésée</span> ET en <span class=\"nc-blue nc-bold\">zones macroscopiquement saines</span></span><br>\n              <strong><span class=\"nc-pink nc-bold\">Crohn</span> :</strong> ulcérations, <span><span class=\"nc-green_bg\">intervalles de muqueuse saine</span></span> (différencie de la <span><span class=\"nc-pink nc-bold\">RCH</span></span>), <span class=\"nc-red_bg\">sténoses</span>/<span class=\"nc-red_bg\">fistules</span> possibles<br>\n              <strong><span><span class=\"nc-pink nc-bold\">RCH</span></span> :</strong> <span class=\"nc-orange_bg\">inflammation</span> continue débutant à la jonction anorectale, <span class=\"nc-blue_bg\">muqueuse granitée</span>, saignement au <span>contact</span>, ulcérations\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Histologie</span></strong></td>\n            <td>Voir objectif « lésions microscopiques » : <span>granulomes épithélioïdes sans nécrose caséeuse</span> évocateurs de Crohn (<span <span=\"\">&gt;30</span> %) ; <span class=\"nc-green_bg\">inflammation superficielle</span> + <span class=\"nc-blue_bg\">micro-</span><span><span class=\"nc-blue_bg\">abcès</span></span><span class=\"nc-blue_bg\"> cryptiques</span> nombreux <span class=\"nc-red_bg\">dans</span> la <span>RCH</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <strong>Recherche d'atteinte iléale :</strong> <span><span class=\"nc-blue_bg\">entéro-IRM</span></span> préférée (pas d'<span>irradiation</span>), <span><span class=\"nc-blue_bg\">entéro-TDM</span></span>, <span><span class=\"nc-blue_bg\">échographie</span></span><br>\n              <strong>Signes radiologiques de <span class=\"nc-pink nc-bold\">Crohn</span> :</strong> épaississement pariétal segmentaire et asymétrique, <span><span class=\"nc-blue_bg\">signe du peigne</span></span> (<span class=\"nc-purple nc-bold\">hyperhémie des mésos</span>), sclérolipomatose, <span><span class=\"nc-orange_bg\">adénopathies</span></span><span class=\"nc-orange_bg\"> de voisinage</span>, <span class=\"nc-red nc-bold\">sténoses</span>/<span class=\"nc-red nc-bold\">fistules</span><br>\n              <strong>LAP :</strong> <span><span class=\"nc-blue_bg\">IRM pelvienne</span></span> si atteinte ano-périnéale clinique<br>\n              <strong>Situations douteuses :</strong> <span>vidéocapsule</span> ou <span>entéroscopie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Sérologies</span> (appoint)</strong></td>\n            <td><span><span class=\"nc-blue_bg\">ASCA</span></span> (<span class=\"nc-red nc-bold\">Crohn</span>) ; <span>pANCA</span> (<span>RCH</span>) — leur positivité n'affirme pas le diagnostic. <span><span class=\"nc-blue_bg\">Coproculture</span></span> + <span>EPS</span> pour éliminer une colite infectieuse</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">\n        <strong>À retenir.</strong> <span>Les</span> <span><span class=\"nc-blue nc-bold\">biopsies</span></span> doivent être prélevées <strong>en <span class=\"nc-blue nc-bold\">zone lésée</span> ET en zone saine</strong> ; l'<span class=\"nc-blue_bg\">entéro-</span><span><span class=\"nc-blue_bg\">IRM</span></span> est privilégiée pour l'<span class=\"nc-red nc-bold\">atteinte</span> du <span class=\"nc-red nc-bold\">grêle</span> car elle <span>n'irradie pas</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span>Syndrome de l</span>’intestin irritable (SII)</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":4},{"id":"282-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales complications des MICI","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink nc-bold\">Crohn</span> : <span class=\"nc-red_bg\">sténoses</span>, occlusion, <span class=\"nc-orange_bg\">fistules</span>, <span class=\"nc-orange_bg\">abcès</span> et lésions anopérinéales. Les deux <span class=\"nc-pink nc-bold\">MICI</span> exposent à dénutrition, <span class=\"nc-blue_bg\">anémie</span>, événements thromboemboliques, complications extra-intestinales et <span class=\"nc-red nc-bold\">cancer colorectal</span> selon ancienneté/<span class=\"nc-red nc-bold\">étendue</span>.</li><li>Colite aiguë grave : au moins six selles sanglantes par jour et au moins un signe de toxicité systémique, selon Truelove–Witts : température &gt; 37,8 °C, fréquence cardiaque &gt; 90/min, Hb &lt; 10,5 g/dL ou VS &gt; 30 mm/h ; les critères modifiés utilisent notamment la CRP.</li><li>Hospitalisation urgente et prise en charge médicochirurgicale coordonnée : bilan infectieux dont C. difficile, évaluation biologique et imagerie selon complications, endoscopie limitée prudente. Rechercher <span class=\"nc-red_bg\">colectasie</span>, <span class=\"nc-red_bg\">perforation</span> et hémorragie sévère ; pas de coloscopie complète préparée en situation menaçante.</li><li>La surveillance carcinologique des <span class=\"nc-pink nc-bold\">MICI</span> coliques est individualisée après plusieurs années d’évolution ; elle est plus rapprochée si cholangite sclérosante, inflammation persistante, dysplasie, <span class=\"nc-orange nc-bold\">sténose</span> ou antécédent familial. Un intervalle unique de trois à cinq ans ne convient pas à tous.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":3}],"astuces":[],"liensGlobaux":[{"href":"https://radiopaedia.org/articles/crohn-disease-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ulcerative-colitis","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Poussée de MICI — Après avoir éliminé une colite infectieuse (coproculture, examen parasitologique des selles)","detail":"<h4>CAT — <span class=\"kw-clinique\">poussée</span> de MICI / colite aiguë grave — Évaluation de la gravité et escalade thérapeutique</h4>","branches":[{"to":"t-non-grave","label":"Critères de Truelove-Witts non remplis (poussée non grave)","color":"green"},{"to":"q-compl","label":"Poussée sévère = colite aiguë grave (≥ 1 critère majeur + ≥ 1 mineur)","color":"red"}]},{"id":"t-non-grave","kind":"terminal","label":"Poussée non grave","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-clinique\">Poussée</span> légère ou modérée ne remplissant pas <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> de <span class=\"kw-def\">Truelove-Witts</span></li></ul><h4>PEC</h4><ul><li>Prise en charge non urgente, adaptée à la sévérité et au type de <span class=\"kw-clinique\">MICI</span></li><li>Traitement de fond <em>(modalités hors programme EDN)</em></li></ul>"},{"id":"q-compl","kind":"decision","label":"Complication chirurgicale d'emblée ? — Colectasie (côlon transverse > 6 cm) · perforation · hémorragie digestive massive","branches":[{"to":"t-chirurgie","label":"Oui","color":"red"},{"to":"q-cortico","label":"Non — colite aiguë grave sans complication","color":"amber"}]},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie en urgence","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-alerte\">Colectasie</span> : dilatation colique (transverse <span class=\"kw-chiffre\">&gt; 6 cm</span>) + signes toxiques</li><li><span class=\"kw-alerte\">Perforation</span> (<span class=\"kw-alerte\">péritonite stercorale</span>)</li><li><span class=\"kw-alerte\">Hémorragie digestive massive</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie en urgence</span> ; <span class=\"kw-imagerie\">TDM</span> systématique devant toute colite aiguë grave (recherche perforation / colectasie)</li></ul>"},{"id":"q-cortico","kind":"decision","label":"Corticoïdes IV 5 jours — réponse à J5 ? — Traitement médical initial de la colite aiguë grave","branches":[{"to":"t-repondeur","label":"Réponse favorable","color":"green"},{"to":"t-2eligne","label":"Échec à J5 (corticorésistance)","color":"red"}]},{"id":"t-repondeur","kind":"terminal","label":"Répondeur aux corticoïdes IV","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticoïdes IV</span> pendant <span class=\"kw-chiffre\">5 jours</span>, réponse favorable</li></ul><h4>Suite</h4><ul><li>Relais et traitement de fond, <span class=\"kw-clinique\">surveillance</span> rapprochée</li><li><span class=\"kw-def\">Suivi</span> de l'activité par <span class=\"kw-bio\">calprotectine fécale</span> / <span class=\"kw-bio\">CRP</span></li></ul>"},{"id":"t-2eligne","kind":"terminal","label":"2ᵉ ligne médicale → colectomie de sauvetage","color":"red","detail":"<h4>2ᵉ ligne médicale</h4><ul><li><span class=\"kw-ttt\">Ciclosporine IV</span> si <span class=\"kw-etio\">RCH</span></li><li><span class=\"kw-ttt\">Infliximab</span> si <span class=\"kw-etio\">maladie de Crohn</span></li></ul><h4>Échec de la 2ᵉ ligne</h4><ul><li><span class=\"kw-ttt\">Colectomie de sauvetage</span> — le traitement chirurgical n'intervient qu'en cas d'échec du traitement médical</li></ul>"}]},"cards":[{"i":"37712e6c89e4","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelles sont les caractéristiques de l'atteinte digestive dans la Maladie de Crohn ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-pink_bg\">Maladie de Crohn</span> peut atteindre <strong>tout le tube digestif</strong>, de la bouche à l'anus. L'<span class=\"nc-orange_bg\">inflammation</span> est <strong><span class=\"nc-blue_bg\">transmurale</span></strong> et <strong>discontinue</strong>, avec des <span class=\"nc-green_bg\">intervalles de muqueuse saine</span>.</p></div>"},{"i":"4cd91bc7f9b6","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelle est la définition générale des Maladies Inflammatoires Chroniques de l'Intestin (MICI) ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-pink nc-bold\">MICI</span> sont des maladies caractérisées par une <strong>inflammation chronique</strong>, intermittente ou <span class=\"nc-yellow_bg\">continue</span>, d'une partie du tube digestif.</p></div>"},{"i":"ed1cdc12989e","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelles sont les caractéristiques de l'atteinte digestive dans la Rectocolite Hémorragique (RCH) ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-pink nc-bold\">Rectocolite Hémorragique</span> (RCH) est limitée au <strong>rectum et au côlon</strong>. L'inflammation est <strong>superficielle et <span class=\"nc-red nc-bold\">continue</span></strong>, avec une extension rétrograde et <span class=\"nc-red nc-bold\">sans intervalle sain</span>.</p></div>"},{"i":"171974408309","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les comorbidités associées aux MICI qui peuvent être dissociées de l'activité intestinale ?","a":"<div class=\"notion-course\"><p>Les comorbidités associées mais dissociées de l'activité des MICI sont :</p><ul><li>La <strong><span class=\"nc-orange_bg\">cholangite sclérosante primitive</span></strong> : <span class=\"nc-red nc-bold\">plus fréquente dans la</span> <span class=\"nc-pink nc-bold\">RCH</span>, elle augmente le <span class=\"nc-red_bg\">risque de</span> carcinome colorectal.</li><li>La <strong>spondylarthrite ankylosante</strong> :<br><ul><li>Forme avec <strong>sacro-iliite radiologique</strong> (10-20 %) : souvent asymptomatique, elle évolue parallèlement à l'atteinte digestive.</li><li>Forme axiale complète (&lt; 5 %) : elle évolue indépendamment de l'atteinte digestive.</li></ul></li></ul></div>"},{"i":"22c08dbe0d49","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les trois manifestations digestives chroniques les plus fréquentes qui doivent faire évoquer une maladie inflammatoire chronique de l'intestin (MICI), en particulier chez un sujet jeune ?","a":"<div class=\"notion-course\"><p>Les trois manifestations digestives chroniques les plus fréquentes évoquant une MICI, surtout chez un sujet jeune, sont :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">diarrhée chronique</span></strong> (sécrétoire ou exsudative)</li><li>Des <strong><span class=\"nc-blue_bg\">douleurs abdominales chroniques</span></strong></li><li>Un <strong><span class=\"nc-red nc-bold\">amaigrissement</span></strong> ou une altération de l'état général</li></ul><p>La présence de <strong><span class=\"nc-orange nc-bold\">symptômes</span> <span class=\"nc-orange nc-bold\">nocturnes</span></strong> qui réveillent le patient est un argument fort en faveur d'une cause organique.</p></div>"},{"i":"366b54352c80","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quels sont les modes de révélation particuliers de la Maladie de Crohn, et quel est un piège classique à éviter concernant les manifestations extra-digestives ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-pink_bg\">Maladie de Crohn</span> peut se révéler de différentes manières :</p><ul><li>Elle peut <span class=\"nc-orange nc-bold\">débuter</span> comme une <strong><span class=\"nc-orange nc-bold\">gastro-entérite</span></strong> dans <strong>10 %</strong> des cas.</li><li>Elle peut être révélée par une <strong>complication</strong>.</li><li>La présence d'une <strong>masse de la fosse iliaque droite</strong> (abcès ou atteinte iléo-cæcale) est possible.</li></ul><p>Un piège classique est de considérer les <strong><span class=\"nc-blue_bg\">ulcérations</span> génitales</strong> comme faisant partie des manifestations extra-digestives des MICI (ce qui est faux). Il faut plutôt penser à la <strong><span class=\"nc-pink nc-bold\">maladie de Behçet</span></strong> devant des <span class=\"nc-blue_bg\">ulcérations</span> génitales.</p></div>"},{"i":"665745114a0d","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les principales manifestations extra-digestives inflammatoires que l'on peut rencontrer au cours des MICI ?","a":"<div class=\"notion-course\"><p>Les principales manifestations extra-digestives inflammatoires des MICI sont :</p><ul><li><strong>Ophtalmologiques</strong> : <strong><span class=\"nc-red_bg\">uvéite</span></strong>, <span class=\"nc-red_bg\">épisclérite</span>, <span class=\"nc-red_bg\">sclérite</span>.</li><li><strong>Cutanéo-muqueuses</strong> : <strong><span class=\"nc-blue_bg\">aphtes buccaux</span></strong>, <strong><span class=\"nc-red_bg\">érythème noueux</span></strong>, <strong><span class=\"nc-red_bg\">pyoderma gangrenosum</span></strong>.</li><li><strong>Articulaires</strong> : <strong><span class=\"nc-blue_bg\">arthrites</span></strong>, <span class=\"nc-blue_bg\">douleurs articulaires</span>.</li></ul></div>"},{"i":"bb295e8b2fdb","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les différentes manifestations anopérinéales pouvant survenir dans la Maladie de Crohn, et quelle est leur fréquence ?","a":"<div class=\"notion-course\"><p>Les manifestations anopérinéales sont présentes chez environ <strong>30 %</strong> des patients atteints de <span class=\"nc-pink_bg\">Maladie de Crohn</span> et sont absentes <span class=\"nc-red_bg\">dans</span> la <span class=\"nc-pink nc-bold\">Rectocolite Hémorragique</span>. Elles peuvent inclure :</p><ul><li>Des <strong>fistules</strong></li><li>Des <strong>fissures</strong> (parfois indolores, latérales)</li><li>Des <strong>ulcérations</strong></li><li>Une <strong><span class=\"nc-orange_bg\">sténose anale</span></strong></li><li>Des <strong>marisques</strong></li></ul></div>"},{"i":"c8ca75123ac1","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les manifestations d'une atteinte recto-colique pouvant orienter vers une MICI, en particulier la Rectocolite Hémorragique (RCH) ?","a":"<div class=\"notion-course\"><p>Les manifestations d'une atteinte recto-colique évocatrices d'une MICI sont :</p><ul><li>Des <strong><span class=\"nc-blue_bg\">rectorragies</span></strong>, <span class=\"nc-red nc-bold\">constantes</span> <span class=\"nc-red_bg\">dans</span> la RCH mais inconstantes <span class=\"nc-red_bg\">dans</span> la <span class=\"nc-pink_bg\">maladie de Crohn</span>.</li><li><span class=\"nc-blue_bg\">Épreintes</span> : douleurs coliques et contractions expulsives précédant l’exonération. Ténesme : tension douloureuse anorectale persistante avec besoin insatisfait.</li><li>Un <strong>syndrome dysentérique</strong> : diarrhée glairo-sanglante chronique.</li></ul></div>"},{"i":"1b814499f3fe","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les complications néoplasiques associées aux MICI et leur surveillance ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink nc-bold\">Crohn</span> : <span class=\"nc-red_bg\">sténoses</span>, occlusion, <span class=\"nc-orange_bg\">fistules</span>, <span class=\"nc-orange_bg\">abcès</span> et lésions anopérinéales. Les deux <span class=\"nc-pink nc-bold\">MICI</span> exposent à dénutrition, <span class=\"nc-blue_bg\">anémie</span>, événements thromboemboliques, complications extra-intestinales et <span class=\"nc-red nc-bold\">cancer colorectal</span> selon ancienneté/<span class=\"nc-red nc-bold\">étendue</span>.</li><li>La surveillance carcinologique des <span class=\"nc-pink nc-bold\">MICI</span> coliques est individualisée après plusieurs années d’évolution ; elle est plus rapprochée si cholangite sclérosante, inflammation persistante, dysplasie, <span class=\"nc-orange nc-bold\">sténose</span> ou antécédent familial. Un intervalle unique de trois à cinq ans ne convient pas à tous.</li></ul></div>"},{"i":"5e98b2b0f90d","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les principales complications locales des MICI, en particulier de la maladie de Crohn ?","a":"<div class=\"notion-course\"><p>Les complications locales des MICI sont :</p><ul><li>Les <strong>sténoses inflammatoires/fibreuses</strong> pouvant entraîner un <strong><span class=\"nc-red nc-bold\">syndrome de</span> <span class=\"nc-red nc-bold\">Koenig</span></strong> ou une occlusion.</li><li>Les <strong><span class=\"nc-orange_bg\">fistules</span></strong> (recto-vaginales, recto-urinaires) et les <strong><span class=\"nc-orange_bg\">abcès</span></strong>.</li><li>Plus rarement, la <strong>perforation</strong> ou les <strong><span class=\"nc-orange_bg\">hémorragies</span></strong>.</li></ul></div>"},{"i":"8f1648302fee","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Comment est définie la colite aiguë grave (CAG) et quelles sont ses complications ?","a":"<div class=\"notion-course\"><ul><li>Colite aiguë grave : au moins six selles sanglantes par jour et au moins un signe de toxicité systémique, selon Truelove–Witts : température &gt; 37,8 °C, fréquence cardiaque &gt; 90/min, Hb &lt; 10,5 g/dL ou VS &gt; 30 mm/h ; les critères modifiés utilisent notamment la CRP.</li><li>Hospitalisation urgente et prise en charge médicochirurgicale coordonnée : bilan infectieux dont C. difficile, évaluation biologique et imagerie selon complications, endoscopie limitée prudente. Rechercher <span class=\"nc-red_bg\">colectasie</span>, <span class=\"nc-red_bg\">perforation</span> et hémorragie sévère ; pas de coloscopie complète préparée en situation menaçante.</li></ul></div>"},{"i":"c5d7cba33453","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quels sont les critères de Truelove-Witts pour définir la colite aiguë grave ?","a":"<div class=\"notion-course\"><ul><li>Colite aiguë grave : au moins six selles sanglantes par jour et au moins un signe de toxicité systémique, selon Truelove–Witts : température &gt; 37,8 °C, fréquence cardiaque &gt; 90/min, Hb &lt; 10,5 g/dL ou VS &gt; 30 mm/h ; les critères modifiés utilisent notamment la CRP.</li></ul></div>"},{"i":"f1c02828c314","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les complications générales des MICI ?","a":"<div class=\"notion-course\"><p>Les complications générales des MICI sont :</p><ul><li>L'<strong>anémie multifactorielle</strong>.</li><li>La <strong>dénutrition / hypoalbuminémie</strong>.</li><li>Le <strong><span class=\"nc-blue_bg\">retard staturo-pondéral</span></strong> chez l'enfant.</li><li>Les <strong><span class=\"nc-orange_bg\">accidents thrombo-emboliques</span></strong>, favorisés par l'inflammation.</li></ul></div>"},{"i":"92d3e3aff327","n":282,"o":"282-2","u":"Examens complémentaires","t":"Connaître les principales lésions macroscopiques et microscopiques de la maladie de Crohn et de la rectocolite hémorragique","q":"Quels sont les points essentiels concernant les principales lésions macroscopiques et microscopiques de la maladie de Crohn et de la rectocolite hémorragique ?","a":"<div class=\"notion-course\"><p><span>Les</span> <span><span class=\"nc-blue nc-bold\">biopsies</span></span> sont réalisées lors de l'<span><span class=\"nc-blue_bg\">endoscopie</span></span> en <strong><span class=\"nc-blue nc-bold\">zone lésée</span> ET en <span class=\"nc-blue nc-bold\">zones macroscopiquement saines</span></strong> (<span class=\"nc-red nc-bold\">atteinte discontinue</span> dans <span class=\"nc-pink nc-bold\">Crohn</span>, <span class=\"nc-green nc-bold\">continue</span> dans la <span><span class=\"nc-pink nc-bold\">RCH</span></span>). Lésions communes : <span><span class=\"nc-purple nc-bold\">ulcérations</span></span>, <span><span class=\"nc-purple nc-bold\">raréfaction des glandes</span></span>, <span>infiltrat lymphoplasmocytaire</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th></th><th><span><span class=\"nc-pink_bg\">Maladie de Crohn</span></span></th><th><span><span class=\"nc-pink nc-bold\">Rectocolite </span><span><span class=\"nc-pink nc-bold\">hémorragique</span></span></span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Lésions macroscopiques</strong></td>\n            <td>\n              <strong>Topographie :</strong> tout le tube digestif, <span class=\"nc-red nc-bold\">atteinte </span><strong><span class=\"nc-red nc-bold\">discontinue</span></strong><br>\n              <strong><span class=\"nc-red_bg\">Anus</span> :</strong> lésions anopérinéales (≈ <span>50 %</span>)<br>\n              <strong>Rectum :</strong> atteint <span class=\"nc-red_bg\">dans</span> seulement <span>25 %</span><br>\n              <strong>Iléon :</strong> <span class=\"nc-blue_bg\">ulcérations</span> iléales (≈ <span>60 %</span>)<br>\n              <strong><span class=\"nc-red_bg\">Sténoses</span> / fistules :</strong> <span class=\"nc-red_bg\">fréquentes</span> (<span class=\"nc-red_bg\">inflammation </span><span><span class=\"nc-red_bg\">transmurale</span></span>)\n            </td>\n            <td><span class=\"nc-pink nc-bold\">RCH</span> typique : <span class=\"nc-red nc-bold\">atteinte</span> muqueuse continue à partir du rectum, limitée au <span class=\"nc-red_bg\">côlon</span> ; des exceptions existent, notamment sous traitement ou en pédiatrie. Fistules et lésions anopérinéales complexes orientent vers <span class=\"nc-pink nc-bold\">Crohn</span>. Toute <span class=\"nc-orange nc-bold\">sténose</span> colique doit être explorée, notamment pour exclure un cancer.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Inflammation</span> &amp; <span class=\"nc-red_bg\">ulcérations</span> (histo)</strong></td>\n            <td>\n              <span class=\"nc-red_bg\">Inflammation </span><span><span class=\"nc-red_bg\">transmurale</span></span> (toutes <span>les</span> couches)<br>\n              <span class=\"nc-red_bg\">Ulcérations</span> <strong><span class=\"nc-red nc-bold\">fissuraires</span></strong><br>\n              <span><span class=\"nc-blue_bg\">Micro-abcès cryptiques</span></span> : <strong>moins nombreux</strong>\n            </td>\n            <td>\n              <span class=\"nc-green_bg\">Inflammation </span><span><span class=\"nc-green_bg\">superficielle</span></span> (muqueuse + sous-muqueuse superficielle)<br>\n              <span class=\"nc-red_bg\">Ulcérations</span> <strong>non <span class=\"nc-red nc-bold\">fissuraires</span></strong><br>\n              <span><span class=\"nc-blue_bg\">Micro-abcès cryptiques</span></span> : <strong><span class=\"nc-blue_bg\">très nombreux</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glandes &amp; infiltrat</strong></td>\n            <td>\n              <span class=\"nc-blue_bg\">Distorsions glandulaires</span> ; <span class=\"nc-green_bg\">mucosécrétion peu altérée</span><br>\n              Infiltrat plasmocytaire du chorion, voire transmural, sous forme de <strong><span><span class=\"nc-red nc-bold\">nodules lymphoïdes</span></span></strong><br>\n              <strong><span><span class=\"nc-yellow_bg\">Granulomes épithélioïdes et gigantocellulaires</span></span></strong><span class=\"nc-yellow_bg\"> sans </span><span><span class=\"nc-yellow_bg\">nécrose</span></span><span class=\"nc-yellow_bg\"> caséeuse</span> : très évocateurs mais présents dans <span>30 %</span> des cas seulement\n            </td>\n            <td>\n              <span class=\"nc-blue_bg\">Bifurcations et distorsions glandulaires</span> ; <span class=\"nc-red_bg\">mucosécrétion </span><strong><span class=\"nc-red_bg\">très altérée</span></strong><br>\n              <span class=\"nc-yellow_bg\">Infiltrat surtout lymphoplasmocytaire du chorion</span> ; <span><span class=\"nc-yellow_bg\">plasmocytose basale</span></span><br>\n              <span>Jamais de granulome épithélioïde</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">\n        <strong>Discriminant clé.</strong> <span>Les</span> <span>granulomes épithélioïdes sans nécrose caséeuse</span> orientent vers la <span><span class=\"nc-pink_bg\">maladie de Crohn</span></span> ; leur absence et la présence d'une <span class=\"nc-orange_bg\">inflammation</span> strictement superficielle <span class=\"nc-green nc-bold\">continue</span> orientent vers la <span><span class=\"nc-pink nc-bold\">RCH</span></span>.\n      </div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les tableaux opposent les présentations typiques. Une <span class=\"nc-pink nc-bold\">RCH</span> traitée peut avoir une distribution moins <span class=\"nc-red nc-bold\">continue</span> ; une iléite de reflux peut accompagner une pancolite. Une sténose colique est possible et doit faire rechercher une dysplasie/cancer. Ces exceptions ne transforment pas toute lésion en <span class=\"nc-pink_bg\">maladie de Crohn</span>.</li></ul></div></div>"},{"i":"c84841bbe873","n":282,"o":"282-3","u":"Physiopathologie","t":"Connaître les principes physiopathologiques de la maladie de Crohn et de la rectocolite hémorragique","q":"Quels sont les points essentiels concernant les principes physiopathologiques de la maladie de Crohn et de la rectocolite hémorragique ?","a":"<div class=\"notion-course\"><p>La cause des <span>MICI</span> n'est <strong>pas identifiée</strong> et la <span>physiopathologie</span> reste mal connue. La réaction <span><span class=\"nc-purple nc-bold\">inflammatoire</span></span> qui induit <span>les</span> lésions intestinales et extra-intestinales fait intervenir des <span>facteurs <span class=\"nc-red nc-bold\">génétiques</span></span>, des <span><span class=\"nc-red nc-bold\">facteurs environnementaux</span></span>, le <span>microbiote fécal (<span class=\"nc-red nc-bold\">dysbiose</span>)</span> et des <span><span class=\"nc-yellow_bg\">anomalies</span> de la réponse immunitaire</span>.</p>\n      <p>L'<span class=\"nc-orange_bg\">inflammation</span> chronique peut entraîner une <span>fibrose intestinale</span> évoluant vers une <strong>sténose</strong> (surtout <span class=\"nc-red nc-bold\">au niveau du grêle dans la </span><span><span class=\"nc-red nc-bold\">maladie de Crohn</span></span>) et augmente le <span class=\"nc-red_bg\">risque de</span> <span><span class=\"nc-red nc-bold\">cancer colorectal</span></span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Facteur</th><th><span><span class=\"nc-pink_bg\">Maladie de Crohn</span></span></th><th><span><span class=\"nc-pink nc-bold\">Rectocolite </span><span><span class=\"nc-pink nc-bold\">hémorragique</span></span></span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Génétique</span></strong></td><td><span class=\"nc-pink nc-bold\">Mutation </span><span><span class=\"nc-pink nc-bold\">CARD15-NOD2</span></span> (aucune utilité diagnostique)</td><td>Facteurs <span class=\"nc-red nc-bold\">génétiques</span> sans marqueur spécifique</td></tr>\n          <tr><td><strong><span>Tabac</span></strong></td><td><span class=\"nc-red_bg\">Effet </span><span><span class=\"nc-red_bg\">aggravant</span></span> (<span>30-50 %</span> de fumeurs) → l'<strong>arrêt du <span>tabac</span> est une priorité</strong></td><td>Effet <strong>protecteur</strong> (<span>&lt; 10 %</span> de fumeurs)</td></tr>\n          <tr><td><strong>Appendicectomie</strong></td><td>ATCD = <strong><span>facteur de risque</span></strong></td><td>ATCD ± facteur <strong>protecteur</strong></td></tr>\n          <tr><td><strong><span>Sérologie</span></strong></td><td><span>ASCA</span> souvent <span class=\"nc-green nc-bold\">positifs</span> (<span class=\"nc-blue nc-bold\">pANCA</span> <span class=\"nc-red nc-bold\">négatifs</span>)</td><td><span><span class=\"nc-blue nc-bold\">pANCA</span></span> souvent <span class=\"nc-green nc-bold\">positifs</span> (ASCA <span class=\"nc-red nc-bold\">négatifs</span>)</td></tr>\n          <tr><td><strong><span>Épidémiologie</span></strong></td><td><span>Prévalence</span> ≈ <span>1/1000</span> ; <span>incidence</span> <span>5-10/100 000/an</span> ; pic <span><span class=\"nc-blue nc-bold\">20-30 ans</span></span></td><td><span>Prévalence</span> ≈ <span>1/1000</span> ; <span>incidence</span> <span>5-10/100 000/an</span> ; <span class=\"nc-pink_bg\">adulte jeune</span> + 2<sup>e</sup> pic à <span><span class=\"nc-blue nc-bold\">60 ans</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><span>Terrain</span> commun : sujets <strong>jeunes</strong>, sex-ratio ≈ <span>1H/1F</span>, <span class=\"nc-brown_bg\">gradient </span><strong><span class=\"nc-brown_bg\">Nord-Sud</span></strong> (incidences <span>les</span> plus élevées en Amérique du Nord et en <span class=\"nc-red nc-bold\">Europe septentrionale</span>).</p>\n      <div class=\"obj-callout warning\">\n        <strong>Piège classique.</strong> La <span class=\"nc-pink nc-bold\">mutation </span><span><span class=\"nc-pink nc-bold\">CARD15-NOD2</span></span> n'a <strong>aucune utilité diagnostique</strong> : ne jamais la proposer comme examen pour poser le diagnostic de <span class=\"nc-pink nc-bold\">Crohn</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — Spondylarthrite <span>inflammatoire</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>L’association épidémiologique du tabac avec la RCH n’est pas une recommandation de fumer. Le sevrage reste recommandé pour la santé globale ; ni ASCA ni pANCA ne remplacent le faisceau diagnostique.</li></ul></div></div>"},{"i":"39757d8d7610","n":282,"o":"282-5","u":"Examens complémentaires","t":"Connaître les examens complémentaires permettant de poser le diagnostic d’une MICI et les arguments du diagnostic : endocopie, histologie, imagerie (IRM)","q":"Quels sont les points essentiels concernant les examens complémentaires permettant de poser le diagnostic d’une MICI et les arguments du diagnostic : endocopie, histologie, imagerie (IRM) ?","a":"<div class=\"notion-course\"><p>Le diagnostic repose sur un <strong>faisceau d'arguments</strong> biologiques, endoscopiques, histologiques et radiologiques — aucun examen n'est isolément spécifique.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Examen</th><th>Apport / arguments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <strong><span><span class=\"nc-blue_bg\">Syndrome inflammatoire</span></span> :</strong> <span><span class=\"nc-brown_bg\">CRP</span></span> ↑, hyperleucocytose à PNN, thrombocytose<br>\n              <strong><span class=\"nc-orange_bg\">Anémie</span> :</strong> <span class=\"nc-brown_bg\">ferriprive</span>, <span><span class=\"nc-brown_bg\">inflammatoire</span></span>, ± carence <span>B12</span> (iléite/résection iléale) ou <span>folates</span> (<span class=\"nc-red nc-bold\">grêle proximal</span>)<br>\n              <strong><span><span class=\"nc-brown_bg\">Albuminémie</span></span> :</strong> <span class=\"nc-orange_bg\">hypoalbuminémie</span> (entéropathie exsudative, <span class=\"nc-orange_bg\">dénutrition</span>)\n            </td>\n          </tr>\n          <tr><td colspan=\"5\">Une calprotectine basse réduit la probabilité d’une MICI active, surtout colique, mais n’exclut pas toutes les atteintes, notamment certaines formes isolées du grêle. Elle s’interprète avec clinique, biologie et explorations.</td></tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Endoscopie</span></span></strong></td>\n            <td>\n              <strong><span><span class=\"nc-blue_bg\">FOGD</span></span> + <span class=\"nc-blue_bg\">iléo-</span><span><span class=\"nc-blue_bg\">coloscopie</span></span></strong> avec <span><span class=\"nc-blue nc-bold\">biopsies</span> en <span class=\"nc-blue nc-bold\">zone lésée</span> ET en <span class=\"nc-blue nc-bold\">zones macroscopiquement saines</span></span><br>\n              <strong><span class=\"nc-pink nc-bold\">Crohn</span> :</strong> ulcérations, <span><span class=\"nc-green_bg\">intervalles de muqueuse saine</span></span> (différencie de la <span><span class=\"nc-pink nc-bold\">RCH</span></span>), <span class=\"nc-red_bg\">sténoses</span>/<span class=\"nc-red_bg\">fistules</span> possibles<br>\n              <strong><span><span class=\"nc-pink nc-bold\">RCH</span></span> :</strong> <span class=\"nc-orange_bg\">inflammation</span> continue débutant à la jonction anorectale, <span class=\"nc-blue_bg\">muqueuse granitée</span>, saignement au <span>contact</span>, ulcérations\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Histologie</span></strong></td>\n            <td>Voir objectif « lésions microscopiques » : <span>granulomes épithélioïdes sans nécrose caséeuse</span> évocateurs de Crohn (<span <span=\"\">&gt;30</span> %) ; <span class=\"nc-green_bg\">inflammation superficielle</span> + <span class=\"nc-blue_bg\">micro-</span><span><span class=\"nc-blue_bg\">abcès</span></span><span class=\"nc-blue_bg\"> cryptiques</span> nombreux <span class=\"nc-red_bg\">dans</span> la <span>RCH</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <strong>Recherche d'atteinte iléale :</strong> <span><span class=\"nc-blue_bg\">entéro-IRM</span></span> préférée (pas d'<span>irradiation</span>), <span><span class=\"nc-blue_bg\">entéro-TDM</span></span>, <span><span class=\"nc-blue_bg\">échographie</span></span><br>\n              <strong>Signes radiologiques de <span class=\"nc-pink nc-bold\">Crohn</span> :</strong> épaississement pariétal segmentaire et asymétrique, <span><span class=\"nc-blue_bg\">signe du peigne</span></span> (<span class=\"nc-purple nc-bold\">hyperhémie des mésos</span>), sclérolipomatose, <span><span class=\"nc-orange_bg\">adénopathies</span></span><span class=\"nc-orange_bg\"> de voisinage</span>, <span class=\"nc-red nc-bold\">sténoses</span>/<span class=\"nc-red nc-bold\">fistules</span><br>\n              <strong>LAP :</strong> <span><span class=\"nc-blue_bg\">IRM pelvienne</span></span> si atteinte ano-périnéale clinique<br>\n              <strong>Situations douteuses :</strong> <span>vidéocapsule</span> ou <span>entéroscopie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Sérologies</span> (appoint)</strong></td>\n            <td><span><span class=\"nc-blue_bg\">ASCA</span></span> (<span class=\"nc-red nc-bold\">Crohn</span>) ; <span>pANCA</span> (<span>RCH</span>) — leur positivité n'affirme pas le diagnostic. <span><span class=\"nc-blue_bg\">Coproculture</span></span> + <span>EPS</span> pour éliminer une colite infectieuse</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">\n        <strong>À retenir.</strong> <span>Les</span> <span><span class=\"nc-blue nc-bold\">biopsies</span></span> doivent être prélevées <strong>en <span class=\"nc-blue nc-bold\">zone lésée</span> ET en zone saine</strong> ; l'<span class=\"nc-blue_bg\">entéro-</span><span><span class=\"nc-blue_bg\">IRM</span></span> est privilégiée pour l'<span class=\"nc-red nc-bold\">atteinte</span> du <span class=\"nc-red nc-bold\">grêle</span> car elle <span>n'irradie pas</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span>Syndrome de l</span>’intestin irritable (SII)</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181c09b46d39d9fcb0396?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
